SET ROLE talus_fn;
CREATE TABLE app.inspection(tenant_id uuid NOT NULL,inspection_id uuid NOT NULL,booking_item_id uuid NOT NULL,trip_id uuid,machine_id uuid NOT NULL,inspection_type text NOT NULL CHECK(inspection_type IN('outbound','inbound')),completed_by_principal_id uuid,status text NOT NULL CHECK(status IN('draft','completed')),completed_at timestamptz,fuel_pct integer CHECK(fuel_pct BETWEEN 0 AND 100),odometer_miles bigint CHECK(odometer_miles>=0),PRIMARY KEY(tenant_id,inspection_id),FOREIGN KEY(tenant_id,booking_item_id) REFERENCES app.booking_item(tenant_id,booking_item_id),FOREIGN KEY(tenant_id,trip_id) REFERENCES app.trip(tenant_id,trip_id),FOREIGN KEY(tenant_id,machine_id) REFERENCES app.machine(tenant_id,machine_id),FOREIGN KEY(tenant_id,completed_by_principal_id) REFERENCES app.principal(tenant_id,principal_id),CHECK((status='completed')=(completed_at IS NOT NULL)));
CREATE TABLE app.inspection_item(tenant_id uuid NOT NULL,inspection_item_id uuid NOT NULL,inspection_id uuid NOT NULL,component_name text NOT NULL,condition text NOT NULL CHECK(condition IN('pass','fail','flagged')),notes text NOT NULL DEFAULT '',photo_evidence_refs text[] NOT NULL DEFAULT '{}',PRIMARY KEY(tenant_id,inspection_item_id),FOREIGN KEY(tenant_id,inspection_id) REFERENCES app.inspection(tenant_id,inspection_id));
CREATE TABLE app.damage_incident(tenant_id uuid NOT NULL,damage_incident_id uuid NOT NULL,machine_id uuid NOT NULL,booking_item_id uuid NOT NULL,trip_id uuid,baseline_inspection_id uuid,reported_by_principal_id uuid NOT NULL,severity text NOT NULL CHECK(severity IN('minor','major','critical')),estimated_repair_cents bigint NOT NULL CHECK(estimated_repair_cents>=0),claimed_amount_cents bigint, status text NOT NULL CHECK(status IN('reported','investigating','assessed','settled')),PRIMARY KEY(tenant_id,damage_incident_id),FOREIGN KEY(tenant_id,machine_id) REFERENCES app.machine(tenant_id,machine_id),FOREIGN KEY(tenant_id,booking_item_id) REFERENCES app.booking_item(tenant_id,booking_item_id),FOREIGN KEY(tenant_id,trip_id) REFERENCES app.trip(tenant_id,trip_id),FOREIGN KEY(tenant_id,baseline_inspection_id) REFERENCES app.inspection(tenant_id,inspection_id),FOREIGN KEY(tenant_id,reported_by_principal_id) REFERENCES app.principal(tenant_id,principal_id));
CREATE OR REPLACE FUNCTION app.m07_sealed_inspection() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status='completed' THEN RAISE EXCEPTION 'COMPLETED_INSPECTION_IMMUTABLE' USING ERRCODE='55000';END IF;RETURN OLD;END;$$;
CREATE TRIGGER m07_inspection_immutable BEFORE UPDATE OR DELETE ON app.inspection FOR EACH ROW EXECUTE FUNCTION app.m07_sealed_inspection();
CREATE OR REPLACE FUNCTION app.m07_sealed_item() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF EXISTS(SELECT 1 FROM app.inspection i WHERE i.tenant_id=OLD.tenant_id AND i.inspection_id=OLD.inspection_id AND i.status='completed') THEN RAISE EXCEPTION 'COMPLETED_INSPECTION_IMMUTABLE' USING ERRCODE='55000';END IF;RETURN OLD;END;$$;
CREATE TRIGGER m07_item_immutable BEFORE UPDATE OR DELETE ON app.inspection_item FOR EACH ROW EXECUTE FUNCTION app.m07_sealed_item();
CREATE TRIGGER m07_incident_append BEFORE UPDATE OR DELETE ON app.damage_incident FOR EACH ROW EXECUTE FUNCTION app.enforce_append_only();
CREATE OR REPLACE FUNCTION app.start_inspection(p_id uuid,p_item uuid,p_trip uuid,p_machine uuid,p_type text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE t uuid:=app.current_context_tenant_id();BEGIN PERFORM app.require_staff_role('staff');INSERT INTO app.inspection VALUES(t,p_id,p_item,p_trip,p_machine,p_type,NULL,'draft',NULL,NULL,NULL);PERFORM app.append_audit('inspection.started','inspection',p_id);RETURN p_id;END;$$;
CREATE OR REPLACE FUNCTION app.complete_inspection(p_id uuid,p_fuel integer,p_odometer bigint) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE t uuid:=app.current_context_tenant_id();BEGIN PERFORM app.require_staff_role('staff');UPDATE app.inspection SET status='completed',completed_at=clock_timestamp(),completed_by_principal_id=app.current_context_principal_id(),fuel_pct=p_fuel,odometer_miles=p_odometer WHERE tenant_id=t AND inspection_id=p_id AND status='draft';IF NOT FOUND THEN RAISE EXCEPTION 'INSPECTION_NOT_COMPLETABLE' USING ERRCODE='P0001';END IF;PERFORM app.append_audit('inspection.completed','inspection',p_id);RETURN p_id;END;$$;
CREATE OR REPLACE FUNCTION app.report_damage_incident(p_id uuid,p_machine uuid,p_item uuid,p_trip uuid,p_base uuid,p_severity text,p_estimate bigint) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE t uuid:=app.current_context_tenant_id();BEGIN PERFORM app.require_staff_role('staff');INSERT INTO app.damage_incident VALUES(t,p_id,p_machine,p_item,p_trip,p_base,app.current_context_principal_id(),p_severity,p_estimate,NULL,'reported');PERFORM app.append_audit('damage.reported','damage_incident',p_id);RETURN p_id;END;$$;
CREATE OR REPLACE FUNCTION app.assess_damage_claim(p_id uuid,p_amount bigint,p_debit uuid,p_credit uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE t uuid:=app.current_context_tenant_id();BEGIN PERFORM app.require_staff_role('manager');UPDATE app.damage_incident SET claimed_amount_cents=p_amount,status='assessed' WHERE tenant_id=t AND damage_incident_id=p_id;PERFORM app.record_deposit_hold(gen_random_uuid(),'damage-'||p_id::text,p_debit,p_credit,p_amount);PERFORM app.append_audit('damage.assessed','damage_incident',p_id);RETURN p_id;END;$$;
DO $$ DECLARE x text;BEGIN FOREACH x IN ARRAY ARRAY['inspection','inspection_item','damage_incident'] LOOP EXECUTE format('ALTER TABLE app.%I ENABLE ROW LEVEL SECURITY;ALTER TABLE app.%I FORCE ROW LEVEL SECURITY;CREATE POLICY tenant_context_policy ON app.%I USING(tenant_id=app.current_context_tenant_id() AND app.context_is_valid()) WITH CHECK(tenant_id=app.current_context_tenant_id() AND app.context_is_valid())',x,x,x);END LOOP;END;$$;
GRANT SELECT,INSERT,UPDATE,DELETE ON app.inspection,app.inspection_item,app.damage_incident TO talus_fn;
REVOKE ALL ON app.inspection,app.inspection_item,app.damage_incident FROM PUBLIC,talus_staff,talus_api,talus_customer;
RESET ROLE;
